const body = $json.body || $json;
const headers = $json.headers || {};

// --------------------------------------------------
// 1. Security check
// --------------------------------------------------
// For local MVP testing, we use the same secret as Workflow 01.
// Later you can replace this with $env.FLOWPILOT_N8N_SHARED_SECRET.
const expectedSecret = $env.FLOWPILOT_INTERNAL_SECRET;
if (!expectedSecret) {
  throw new Error('FLOWPILOT_INTERNAL_SECRET env var is not set in n8n.');
}

const incomingSecret =
  headers['x-flowpilot-secret'] ||
  headers['X-FlowPilot-Secret'] ||
  body.flowpilot_secret ||
  '';

if (incomingSecret !== expectedSecret) {
  return {
    valid: false,
    errors: ['UNAUTHORIZED'],
    message: 'Invalid FlowPilot secret.'
  };
}

// --------------------------------------------------
// 2. Helpers
// --------------------------------------------------
const clean = (value, max = 1000) => {
  if (value === undefined || value === null) return '';
  return String(value).trim().substring(0, max);
};

const allowedUsers = ['user_001', 'user_010', 'user_020', 'user_030'];

const requestedBy = allowedUsers.includes(body.requested_by)
  ? body.requested_by
  : 'user_030';

// --------------------------------------------------
// 3. Required fields validation
// --------------------------------------------------
const errors = [];

const leadId = clean(body.lead_id || body.id, 100);
const email = clean(body.email, 255).toLowerCase();

if (!leadId) {
  errors.push('LEAD_ID_REQUIRED');
}

if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) {
  errors.push('VALID_EMAIL_REQUIRED');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors,
    message: 'Communication draft request rejected by validation.'
  };
}

// --------------------------------------------------
// 4. Normalize lead context
// --------------------------------------------------
const now = new Date().toISOString();

return {
  valid: true,
  errors: [],
  warnings: [],
  workflow_name: 'FP_CRM_02_Communication_Draft',
  process: 'CRM',
  started_at: now,
  requested_by: requestedBy,

  lead: {
    lead_id: leadId,
    full_name: clean(body.full_name || body.name, 200),
    assigned_to_name: clean(body.assigned_to_name, 200),
    email,
    phone: clean(body.phone, 80),
    company_name: clean(body.company_name || body.company || body.organization, 200),
    source: clean(body.source || 'crm_ui', 100),

    message: clean(body.message || body.original_message || '', 5000),
    product_service: clean(body.product_service || body.product || 'AI CRM Automation', 200),

    customer_status: clean(body.customer_status || 'prospect', 100),
    status: clean(body.status || 'hot', 100),
    priority: clean(body.priority || 'high', 100),

    sentiment: clean(body.sentiment || '', 100),
    intention: clean(body.intention || '', 100),
    urgency: clean(body.urgency || '', 100),
    ai_summary: clean(body.ai_summary || '', 5000),
    recommended_action: clean(body.recommended_action || '', 5000),
    next_action: clean(body.next_action || '', 1000),

    estimated_value: Number(body.estimated_value || 0) || null,
    customer_category: clean(body.customer_category || '', 100),
    location: clean(body.location || '', 200),
    notes: clean(body.notes || '', 2000),

    draft_type: clean(body.draft_type || 'initial', 40),
    email_purpose: clean(body.email_purpose || '', 200),
    response_context: clean(body.response_context || 'first_touch', 60),
    generation_instruction: clean(body.generation_instruction || '', 2000),
    previous_email_subject: clean(body.previous_email_subject || '', 500),
    previous_email_body: clean(body.previous_email_body || '', 8000),
    previous_email_sent_at: clean(body.previous_email_sent_at || '', 60),

    requested_by: requestedBy
  }
};

