const prepared = $('🧾 Prepare Communication Context').first().json;
const lead = prepared.lead || {};
const startedAt = prepared.started_at;

const clean = (value, max = 5000) => {
  if (value === undefined || value === null) return '';
  return String(value).trim().substring(0, max);
};

const escapeHtml = (value) => {
  return clean(value, 10000)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

const stripHtml = (value) => {
  return clean(value, 10000)
    .replace(/<br\s*\/?>/gi, ' ')
    .replace(/<\/p>/gi, ' ')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
};

const normalizeLower = (value) => clean(value, 500).toLowerCase();

const fullName = clean(lead.full_name, 200);
const companyName = clean(lead.company_name, 200);
const productService = clean(lead.product_service || 'TAC-TIC', 200);
const originalMessage = clean(lead.message, 1200);
const aiSummary = clean(lead.ai_summary, 1200);
const recommendedAction = clean(lead.recommended_action, 1000);
const nextAction = clean(lead.next_action, 1000);
const intention = normalizeLower(lead.intention || 'unknown');
const urgency = normalizeLower(lead.urgency || 'medium');
const priority = normalizeLower(lead.priority || 'medium');

const displayName = fullName || 'Madame, Monsieur';

// Intention de generation envoyee par FastAPI -> draft_type stocke en base.
// 'information' est une relance de clarification: on la stocke en follow_up.
const draftTypeIn = normalizeLower(lead.draft_type || 'initial');
const DRAFT_TYPE_MAP = {
  initial: 'sales',
  follow_up: 'follow_up',
  reactivation: 'reactivation',
  information: 'follow_up'
};
const draftTypeOut = DRAFT_TYPE_MAP[draftTypeIn] || 'sales';
const companyPart = companyName ? ` pour ${escapeHtml(companyName)}` : '';

const productLower = productService.toLowerCase();
const messageLower = originalMessage.toLowerCase();

const isDemoNeed =
  intention.includes('demo') ||
  messageLower.includes('demo') ||
  messageLower.includes('démonstration') ||
  messageLower.includes('demonstration');

const isQuoteNeed =
  intention.includes('purchase') ||
  messageLower.includes('devis') ||
  messageLower.includes('prix') ||
  messageLower.includes('tarif') ||
  messageLower.includes('acheter');

const isSupportNeed =
  intention.includes('support') ||
  messageLower.includes('support') ||
  messageLower.includes('problème') ||
  messageLower.includes('probleme');

const isAutomationNeed =
  productLower.includes('automation') ||
  productLower.includes('automatisation') ||
  messageLower.includes('automatiser') ||
  messageLower.includes('automatisation') ||
  messageLower.includes('workflow');

const isCrmNeed =
  productLower.includes('crm') ||
  messageLower.includes('crm') ||
  messageLower.includes('lead') ||
  messageLower.includes('prospect');

const inferCta = () => {
  if (isDemoNeed) return 'book_demo';
  if (isQuoteNeed) return 'schedule_call';
  if (isSupportNeed) return 'reply_email';
  return 'schedule_call';
};

// --------------------------------------------------
// 1. Parse OpenRouter response (fail loudly, never fake a draft)
// --------------------------------------------------
let draft = {};
let llmFailure = null;

// OpenRouter renvoie {error:{message,code}} quand le modele est mort/indispo.
// L'ancien code faisait `content || '{}'` -> JSON.parse OK -> echec invisible.
const llmError = $json && $json.error ? $json.error : null;
const rawContent =
  $json && $json.choices && $json.choices[0] && $json.choices[0].message
    ? $json.choices[0].message.content
    : null;

if (llmError) {
  llmFailure =
    clean(llmError.message || 'OpenRouter returned an error', 500) +
    (llmError.code ? ' (code ' + llmError.code + ')' : '');
} else if (!rawContent) {
  llmFailure = 'OpenRouter returned no completion content.';
} else {
  try {
    draft = JSON.parse(
      String(rawContent).replace(/```json/g, '').replace(/```/g, '').trim()
    );
  } catch (error) {
    llmFailure = 'AI response was not valid JSON: ' + clean(error.message, 200);
  }
}

// --------------------------------------------------
// 2. Validate AI output - no silent static fallback
// --------------------------------------------------
const parsedSubject = clean(draft.email_subject, 300);
const parsedBody = clean(draft.email_body, 10000);
const parsedBodyText = stripHtml(parsedBody);

if (!llmFailure && (!parsedBody || parsedBodyText.length < 120)) {
  llmFailure = 'AI returned an empty or too short email body.';
}

const now = new Date().toISOString();
const durationSeconds = Math.round((Date.now() - new Date(startedAt).getTime()) / 1000);

// Arret net : ne JAMAIS renvoyer un template non-IA comme un brouillon genere.
if (llmFailure) {
  return {
    lead_id: lead.lead_id,
    draft_type: draftTypeOut,
    generated_by: 'none',
    email_subject: null,
    email_body: null,
    communication_status: 'llm_generation_failed',
    error_message: llmFailure,
    next_action: 'Fix the AI generation error and retry the draft generation',
    workflow_execution: {
      workflow_name: 'FP CRM 02 - Intelligent Communication Draft',
      process: 'CRM',
      related_object_type: 'crm_lead',
      related_object_id: lead.lead_id,
      trigger_source: 'fastapi',
      status: 'error',
      started_at: startedAt,
      finished_at: now,
      duration_seconds: durationSeconds,
      input_summary: 'Generate communication draft for ' + lead.email,
      output_summary: 'LLM generation failed',
      result_summary: 'Communication draft generation failed; no draft was created.',
      error_message: llmFailure,
      agent_name: 'CRM Communication Agent'
    },
    agent_run: {
      agent_id: 'crm_communication_agent',
      agent_name: 'CRM Communication Agent',
      process: 'CRM',
      requested_by: lead.requested_by || 'user_030',
      status: 'error',
      started_at: startedAt,
      finished_at: now,
      input_summary: JSON.stringify({
        lead_id: lead.lead_id,
        draft_type: draftTypeIn
      }).substring(0, 500),
      output_summary: 'LLM generation failed',
      error_message: llmFailure
    }
  };
}

const emailSubject = clean(parsedSubject, 300);
const emailBody = clean(parsedBody, 10000);

const allowedStatuses = ['draft_generated', 'communication_draft_generated', 'waiting_review'];
const communicationStatus = allowedStatuses.includes(clean(draft.communication_status, 100))
  ? clean(draft.communication_status, 100)
  : 'draft_generated';

const allowedTones = ['professional', 'friendly', 'urgent', 'informative'];
const tone = allowedTones.includes(clean(draft.tone, 100))
  ? clean(draft.tone, 100)
  : urgency === 'high'
    ? 'urgent'
    : 'professional';

const allowedCtas = ['schedule_call', 'book_demo', 'reply_email', 'send_documents'];
const cta = allowedCtas.includes(clean(draft.cta, 100))
  ? clean(draft.cta, 100)
  : inferCta();

const shortSummary = clean(
  draft.short_summary ||
    'AI communication draft (' + draftTypeIn + ') generated for ' +
      (fullName || companyName || 'lead') + ' about ' + productService + '.',
  1000
);

// --------------------------------------------------
// 3. Build FastAPI communication-result payload
// --------------------------------------------------
return {
  lead_id: lead.lead_id,

  draft_type: draftTypeOut,
  generated_by: 'llm',
  email_subject: emailSubject,
  email_body: emailBody,
  communication_status: communicationStatus,
  email_priority: lead.priority || 'medium',
  tone,
  cta,

  // Important: no automatic email sending.
  // The next action remains human validation.
  next_action: 'Review generated communication draft before any email is sent',

  interaction: {
    interaction_type: 'communication_draft',
    channel: 'email',
    summary: `Sales communication draft generated for human review. Subject: ${emailSubject}`
  },

  workflow_execution: {
    workflow_name: 'FP CRM 02 - Intelligent Communication Draft',
    process: 'CRM',
    related_object_type: 'crm_lead',
    related_object_id: lead.lead_id,
    trigger_source: 'fastapi',
    status: 'success',
    started_at: startedAt,
    finished_at: now,
    duration_seconds: durationSeconds,
    input_summary: `Generate communication draft for ${lead.email}`,
    output_summary: emailSubject,
    result_summary: 'AI communication draft generated for human validation.',
    error_message: null,
    agent_name: 'CRM Communication Agent'
  },

  agent_run: {
    agent_id: 'crm_communication_agent',
    agent_name: 'CRM Communication Agent',
    process: 'CRM',
    requested_by: lead.requested_by || 'user_030',
    status: 'success',
    started_at: startedAt,
    finished_at: now,
    input_summary: JSON.stringify({
      lead_id: lead.lead_id,
      email: lead.email,
      intention: lead.intention,
      urgency: lead.urgency,
      priority: lead.priority,
      product_service: lead.product_service,
      ai_summary: lead.ai_summary,
      recommended_action: lead.recommended_action
    }).substring(0, 500),
    output_summary: shortSummary,
    error_message: null
  }
};
